            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
            case REVIEW -> this == DRAFT;
        };
    }

    /** Whether a claim of this status may move to another person: DRAFT, OPEN or PENDING. */
    public boolean canMove() {
        return this == DRAFT || this == OPEN || this == PENDING;
    }

    /** Whether the claim is open: OPEN, or PENDING, which is handled as open. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }

    /** The audit event recorded when a claim moves to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DELETED -> "CLAIM_DELETED";
            case DRAFT -> "CLAIM_DRAFTED";
            case REVIEW -> "CLAIM_REVIEW";
        };
    }

    /** The audit event recorded when a claim moves from {@code from} to this status: a PENDING claim
     *  settled is CLAIM_APPROVED, one moved back to OPEN is CLAIM_REJECTED, and a DELETED claim moved
     *  back to DRAFT is CLAIM_RESTORED. A REVIEW claim moved to OPEN is CLAIM_REVIEWED (then recorded
     *  as CLAIM_OPENED too, see {@link AuditClaimStatus}). */
    public String event(ClaimStatus from) {
        if (from == DELETED && this == DRAFT) {
            return "CLAIM_RESTORED";
        }
        if (from == PENDING && this == SETTLED) {
            return "CLAIM_APPROVED";
        }
        if (from == PENDING && this == OPEN) {
            return "CLAIM_REJECTED";
        }
        if (from == REVIEW && this == OPEN) {
            return "CLAIM_REVIEWED";
        }
        return event();
    }
}

package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;

/** A person on a sheet. {@code grades} are their grades (each one of A, B or C) by the date each applies
 *  from, the first from {@link #START} (the beginning of time); {@code version} moves on with each stored edit;
 *  {@code retiredFrom} is the date they are retired from (null while not retired); {@code pastRetirements}
 *  the retirements they were unretired from, oldest first; {@code holds} their holds,
 *  oldest first: their OPEN claims dated within one count in no live total unless a statement bound them, nor do
 *  any of their OPEN claims once the sheet's today reaches their retirement date. */
public class Person {
    /** The from-date of a person's first grade: the beginning of time. */
    public static final LocalDate START = LocalDate.of(1, 1, 1);

    private final long id;
    private final String sheetId;
    private String name;
    private final NavigableMap<LocalDate, String> grades;
    private long version;
    private LocalDate retiredFrom;
    private final List<Hold> holds = new ArrayList<>();
    private final List<PastRetirement> pastRetirements = new ArrayList<>();
    private final List<Snapshot> snapshots = new ArrayList<>();
    private final List<String> aliases = new ArrayList<>();
    private LocalDate recordFrom;
    private Integer terms;
    private final NavigableMap<LocalDate, Integer> datedTerms = new TreeMap<>();
    private LocalDate termsRecordFrom;
    private boolean termsChanged;
    private String contact;
    private boolean contactChanged;
    private String origin;
    private LocalDate arrivedOn;
    private String tags;
    private Flag flag;
    private String approver;

    public Person(long id, String sheetId, String name, NavigableMap<LocalDate, String> grades, long version) {
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        this.grades = new TreeMap<>(grades);
        this.version = version;
    }

    public Person(long id, String sheetId, String name, NavigableMap<LocalDate, String> grades, long version,
            LocalDate retiredFrom, List<Hold> holds) {
        this(id, sheetId, name, grades, version);
        this.retiredFrom = retiredFrom;
        this.holds.addAll(holds);
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    /** The grade in force on the date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate on) {
        Map.Entry<LocalDate, String> e = grades.floorEntry(on);
        return e == null ? grades.firstEntry().getValue() : e.getValue();
    }
    /** Every grade by the date it applies from ({@link #START} for the first). */
    public NavigableMap<LocalDate, String> getGrades() { return grades; }
    /** The from-date of the grade the next save records, null when it records none. */
    public LocalDate getRecordFrom() { return recordFrom; }
    public long getVersion() { return version; }
    public LocalDate getRetiredFrom() { return retiredFrom; }
    /** Retired as soon as a date is set, whatever the date. */
    public boolean isRetired() { return retiredFrom != null; }
    /** Whether their retirement date is reached on the date: from then their OPEN (and PENDING) claims count
     *  in no live total unless a statement bound them, as a hold's would. */
    public boolean retiredOn(LocalDate date) { return retiredFrom != null && date != null && !date.isBefore(retiredFrom); }
    /** Whether the person has any hold, whatever its dates. */
    public boolean isHeld() { return !holds.isEmpty(); }
    /** Their holds, oldest first. */
    public List<Hold> getHolds() { return holds; }
    /** Whether a hold of theirs covers the date. */
    public boolean heldOn(LocalDate date) { return holds.stream().anyMatch(h -> h.covers(date)); }
    public void addHold(Hold hold) { holds.add(hold); }
    /** Their aliases: other names they are found by, sorted as names are compared. */
    public List<String> getAliases() { return aliases; }
    public void setName(String name) { this.name = name; }
    /** Records the grade from the date at the next save, keeping the others. */
    public void recordGrade(LocalDate from, String grade) {
        grades.put(from, grade);
        recordFrom = from;
    }
    /** Their own terms (whole days) from the beginning of time, until the first dated terms; null when they have none. */
    public Integer getTerms() { return terms; }
    /** Sets their own terms from the beginning of time, noting whether they differ from the ones they had. */
    public void setTerms(Integer terms) {
        termsChanged = !java.util.Objects.equals(this.terms, terms);
        this.terms = terms;
    }
    /** Their own terms by the date each applies from, after those from the beginning of time (a null value:
     *  none of their own from that date). */
    public NavigableMap<LocalDate, Integer> getDatedTerms() { return datedTerms; }
    /** Their own terms in force on the date: the dated ones with the latest from-date on or before it, else
     *  those from the beginning of time; null when they have none then. */
    public Integer termsOn(LocalDate on) {
        Map.Entry<LocalDate, Integer> e = datedTerms.floorEntry(on);
        return e == null ? terms : e.getValue();
    }
    /** Records their own terms (null for none) from the date at the next save, keeping the others (replacing
     *  those from the same date), noting whether that changed them. */
    public void recordTerms(LocalDate from, Integer terms) {
        termsChanged = !datedTerms.containsKey(from) || !java.util.Objects.equals(datedTerms.get(from), terms);
        datedTerms.put(from, terms);
        termsRecordFrom = from;
    }
    /** The from-date of the dated terms the next save records, null when it records none. */
    public LocalDate getTermsRecordFrom() { return termsRecordFrom; }
    /** Whether the last {@link #setTerms} or {@link #recordTerms} changed their terms (or as last noted). */
    public boolean isTermsChanged() { return termsChanged; }
    /** Notes whether an edit changed their terms, overriding what the last set or record noted. */
    public void noteTermsChanged(boolean changed) { termsChanged = changed; }
    /** Their contact (trimmed, lower-cased), null when they have none. */
    public String getContact() { return contact; }
    /** Sets their contact, noting whether it differs from the one they had. */
    public void setContact(String contact) {
        contactChanged = !java.util.Objects.equals(this.contact, contact);
        this.contact = contact;
    }
    /** Whether the last {@link #setContact} changed their contact. */
    public boolean isContactChanged() { return contactChanged; }
    /** Their tags as stored (see {@link net.officefloor.hq.app.claim.Tags}), null when they have none. */
    public String getTags() { return tags; }
    public void setTags(String tags) { this.tags = tags; }
    /** The sheet they were transferred from, null when they were not transferred here. */
    public String getOrigin() { return origin; }
    public void setOrigin(String origin) { this.origin = origin; }
    /** The sheet's today on which a transfer brought them here, null when they were not transferred here. */
    public LocalDate getArrivedOn() { return arrivedOn; }
    public void setArrivedOn(LocalDate arrivedOn) { this.arrivedOn = arrivedOn; }
    public void setVersion(long version) { this.version = version; }
    public void setRetiredFrom(LocalDate retiredFrom) { this.retiredFrom = retiredFrom; }
    /** Their past retirements (each ended by unretiring them), oldest first. */
    public List<PastRetirement> getPastRetirements() { return pastRetirements; }
    /** Their flag, null when they were never flagged (it may be past its until-date). */
    public Flag getFlag() { return flag; }
    public void setFlag(Flag flag) { this.flag = flag; }
    /** Their approver, a user who may approve or reject their PENDING claims as a steward may (null when none). */
    public String getApprover() { return approver; }
    public void setApprover(String approver) { this.approver = approver; }
    /** Whether their flag is in force on the date: only a steward may open a claim of theirs then. */
    public boolean flaggedOn(LocalDate date) { return flag != null && flag.inForceOn(date); }
    /** Their snapshots, one per SNAPSHOT written for them, oldest first. */
    public List<Snapshot> getSnapshots() { return snapshots; }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.statement.StatementSummary;

/** A person as the front end reads it: the grade in force on the sheet's today and every grade with the
 *  date (yyyy-MM-dd) it applies from (null for the first, from the beginning of time), with their
 *  statement count and the last statement's due-total and date (null when none was taken), whether they
 *  are retired and from when (null when not) and whether the sheet's today has reached that date, whether they have any hold
 *  and each hold's from-date and to-date (null for no end), the ids of their patrons (in the order named), and their own terms
 *  in force on the sheet's today (whole days, null when none), their contact (null when none) and their aliases, sorted as names are compared, and whether they clash: their
 *  name or an alias is used as a name or alias on another sheet of the sheet's tree, and the sheet they were
 *  transferred from (null when they were not), and their past retirements, oldest first, and their tags, sorted, and their snapshots, oldest first, and their statements still standing, oldest first (by date), and the reason of their flag while it is in force on the sheet's today (null when none is), and their approver (null when none). */
public record PersonResponse(long id, String name, String grade, List<GradeFrom> grades, long version,
        int statementCount, String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldFrom> holds, List<Long> patronIds, Integer terms,
        boolean retiredNow, String contact, List<String> aliases, boolean clashing,
        String origin, List<RetirementFrom> pastRetirements, List<String> tags,
        List<SnapshotLine> snapshots, List<StatementSummary.Line> statements, String flag, String approver) {

    /** A snapshot's day being left (yyyy-MM-dd) and the due-total as it stood then (two decimals, or n/a). */
    public record SnapshotLine(String day, String dueTotal) {
    }

    /** A past retirement's from-date and to-date, the day they were unretired (yyyy-MM-dd). */
    public record RetirementFrom(String from, String to) {
    }

    /** A hold's from-date and to-date (yyyy-MM-dd; null for no end). */
    public record HoldFrom(String from, String to) {
    }

    /** A grade and the date it applies from (null for from the beginning of time). */
    public record GradeFrom(String grade, String from) {
    }

    public static PersonResponse from(Person p, LocalDate today, StatementSummary s, List<Long> patronIds,
            boolean clashing) {
        List<GradeFrom> grades = p.getGrades().entrySet().stream()
                .map(e -> new GradeFrom(e.getValue(), Person.START.equals(e.getKey()) ? null : e.getKey().toString()))
                .toList();
        return new PersonResponse(p.getId(), p.getName(), p.gradeOn(today), grades, p.getVersion(), s.count(),
                s.lastDueTotal(), s.lastDate(), p.isRetired(),
                p.getRetiredFrom() == null ? null : p.getRetiredFrom().toString(), p.isHeld(),
                p.getHolds().stream().map(h -> new HoldFrom(h.from().toString(), h.to() == null ? null : h.to().toString()))
                        .toList(),
                patronIds, p.termsOn(today), p.retiredOn(today), p.getContact(),
                List.copyOf(p.getAliases()), clashing, p.getOrigin(),
                p.getPastRetirements().stream().map(r -> new RetirementFrom(r.from().toString(), r.to().toString()))
                        .toList(),
                net.officefloor.hq.app.claim.Tags.list(p.getTags()),
                p.getSnapshots().stream().map(n -> new SnapshotLine(n.day().toString(), n.dueTotal())).toList(),
                s.lines(), p.flaggedOn(today) ? p.getFlag().reason() : null,
                p.getApprover());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;

/** The person form's rules, shared by the form and the people import. */
public final class PersonRules {
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private PersonRules() {
    }

    /** The person form's rules for a name, grade, from-date, terms, terms from-date, contact and tags: the request as stored
     *  (name trimmed, blanks as none, contact lower-cased, tags as {@link net.officefloor.hq.app.claim.Tags} stores them), or refused. */
    public static PersonRequest check(PersonRequest request) throws InvalidSheetException {
        if (request == null || request.name() == null || request.name().trim().isEmpty()) {
            throw new InvalidSheetException("A name is required");
        }
        if (request.grade() == null || !GRADES.contains(request.grade())) {
            throw new InvalidSheetException("The grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        try {
            if (!from.isEmpty()) {
                LocalDate.parse(from);
            }
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + from);
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
            throw new InvalidSheetException("The terms must be a whole number of days, 0 or more, or blank");
        }
        String termsFrom = request.termsFrom() == null ? "" : request.termsFrom().trim();
        try {
            if (!termsFrom.isEmpty()) {
                LocalDate.parse(termsFrom);
            }
        } catch (DateTimeParseException e) {
            throw new InvalidSheetException("Not a date: " + termsFrom);
        }
        String contact = request.contact() == null ? "" : request.contact().trim().toLowerCase(java.util.Locale.ROOT);
        // Stored and compared without the spaces around the name; a blank from-date as none.
        return new PersonRequest(request.name().trim(), request.grade(), from.isEmpty() ? null : from,
                request.user(), request.version(),
                terms.isEmpty() ? null : String.valueOf(Integer.parseInt(terms)), contact.isEmpty() ? null : contact,
                net.officefloor.hq.app.claim.Tags.normalise(request.tags()), termsFrom.isEmpty() ? null : termsFrom);
    }

    /** Refuses a name another person on the sheet, or anyone on another sheet of its tree, has as a name or
     *  alias, or a contact another person on the sheet has. */
    public static void refuseTaken(String sheetId, PersonRequest request, PersonStore store, SettingStore settings)
            throws DuplicateNameException, DuplicateContactException {
        if (store.nameTaken(sheetId.trim(), request.name(), null)
                || store.usedOn(settings.tree(sheetId.trim()), request.name())) {
            throw new DuplicateNameException(request.name());
        }
        if (request.contact() != null && store.contactTaken(sheetId.trim(), request.contact(), null)) {
            throw new DuplicateContactException(request.contact());
        }
    }

    /** Records the terms (null for none) as an edit does: from the terms from-date (yyyy-MM-dd), keeping the
     *  ones already recorded, or when it is null from the beginning of time. */
    public static void applyTerms(Person person, String terms, String termsFrom) {
        Integer days = terms == null ? null : Integer.valueOf(terms);
        if (termsFrom == null) {
            person.setTerms(days);
        } else {
            person.recordTerms(LocalDate.parse(termsFrom), days);
        }
    }

    /** Records the grade from the from-date (yyyy-MM-dd, null for the sheet's today), as an edit does: nothing
     *  when the from-date is null and the grade is the one in force on the sheet's today. */
    public static void applyGrade(Person person, String grade, String gradeFrom, LocalDate today) {
        if (gradeFrom == null && grade.equals(person.gradeOn(today))) {
            return;
        }
        person.recordGrade(gradeFrom == null ? today : LocalDate.parse(gradeFrom), grade);
    }
}
package net.officefloor.hq.app.rollup;

import java.util.Map;

/** The sheet's figures at one moment: each person's claimed, due-total and overdue-total (by person id, in
 *  list order) and the sheet's claimed-total, due-total and overdue-total, all as shown (two decimals, n/a). */
public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {

    /** A person's figures; {@code name} is what the ROLLUP line shows, not part of the comparison. */
    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal)
                    && overdueTotal.equals(other.overdueTotal);
        }
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogStore;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.ClaimStore;
import net.officefloor.hq.app.claim.Lateness;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.rate.RateStore;
import net.officefloor.hq.app.setting.SettingStore;
import net.officefloor.hq.app.sheet.SheetStore;
import org.springframework.stereotype.Service;

/**
 * Works out the sheet's figures as the screen shows them, and records in the audit file how a change
 * moved them: ROLLUP sheet=<id> by=<user> person=<name> claimed=<0.00> due-total=<0.00 or n/a>
 * overdue-total=<0.00> for each person whose figures changed (a person new to the sheet counts as changed), in
 * list order (by their positions), then TOTALS sheet=<id> by=<user> claimed-total=<0.00> due-total=<0.00>
 * overdue-total=<0.00> when any of the sheet's totals changed; the sheet's due-total and overdue-total leave out
 * the single highest and the single lowest person's figure when three or more people have one (n/a is no figure). A person's overdue-total is the due (late charge
 * included, skipping n/a) of their counting claims that are OPEN or PENDING with a due-by (plus any grace days of their grade, see {@link Lateness}) before today. A person's due-total is at most the sheet's cap. A change that moves no figure records nothing here.
 * After those lines, while the sheet's alert threshold is set, ALERT sheet=<id> by=<user> name=<name> due-total=<0.00>
 * for each person whose due-total the change took from at or below it (or no due-total) to above it, in list order.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonStore people;
    private final ClaimStore claims;
    private final RateStore rates;
    private final SheetStore sheets;
    private final SettingStore settings;
    private final Audit audit;
    private final ClaimLogStore log;

    public RollupService(PersonStore people, ClaimStore claims, RateStore rates, SheetStore sheets, SettingStore settings,
            Audit audit, ClaimLogStore log) {
        this.people = people;
        this.log = log;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        BigDecimal cap = settings.cap(sheetId);
        Lateness lateness = lateness(sheetId, today, all);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
            boolean fixed = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !countsClaimed(claim, person, today)) {
                    continue;
                }
                // A claim that corrects another counts toward due but not toward claimed.
                if (claim.getCorrects() == null || claim.getCorrects().isBlank()) {
                    claimed = claimed.add(claim.getAmount());
                }
                // A held claim stays in claimed, but leaves the due figures while held.
                if (!counts(claim, person, today)) {
                    continue;
                }
                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
                if (figure != null) {
                    due = due.add(figure);
                    if (lateness.overdue(claim)) {
                        overdue = overdue.add(figure);
                    }
                }
                // A figure at a grade other than the one in force today, or at a rate that ended before
                // today, does not hang on today's grade's rate.
                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
                        || (figure != null && (!person.gradeOn(claim.getDate()).equals(person.gradeOn(today))
                                || rates.forClaim(claim).endsBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), today)));
            }
            boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue);
            due = SettingStore.capped(due, cap);
            if (!na) {
                dues.add(due);
            }
            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due),
                    shown(overdue)));
        }
        return new Rollup(figures, shown(claimedTotal), shown(trimmed(dues)), shown(trimmed(overdues)));
    }

    /** The sum of people's figures, leaving out the single highest and the single lowest when three or more
     *  people have one. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = new ArrayList<>(figures);
        sorted.sort(null);
        if (sorted.size() >= 3) {
            sorted = sorted.subList(1, sorted.size() - 1);
        }
        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Each person's due-total of their claims due by a date in from..to (inclusive) that count by the status they
     *  had at the end of {@code to} (see {@link #countsAt}), by person id in the order they were added: the
     *  sum of their figures as shown now, skipping n/a, as the screen shows a person's due-total for a
     *  period. A period's due-total is the sum of these. */
    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        Lateness lateness = lateness(sheetId, today, all);
        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId()
                        || !countsAt(claim, atEnd.get(claim.getId()), person, today)
                        || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
                    continue;
                }
                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
                if (figure != null) {
                    total = total.add(figure);
                }
            }
            totals.put(person.getId(), total);
        }
        return totals;
    }

    /** Each person's figure carried into a period ending on {@code to}, by person id in the order they were added:
     *  the sum of the figures (as shown now, skipping n/a) of their claims due by a date in one of the
     *  {@code earlier} periods (each from..to, inclusive) that were OPEN or PENDING at the end of {@code to} and
     *  count then (see {@link #countsAt}), as the screen shows a person's carried figure for an open period. */
    public Map<Long, BigDecimal> carriedByPerson(String sheetId, LocalDate to, List<LocalDate[]> earlier) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.list(sheetId);
        Lateness lateness = lateness(sheetId, today, all);
        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            for (Claim claim : all) {
                ClaimStatus status = atEnd.get(claim.getId());
                if (claim.getPersonId() != person.getId() || status == null || !status.isOpen()
