389	                }
390	                // A claim that corrects another counts toward due but not toward claimed.
391	                if (claim.getCorrects() == null || claim.getCorrects().isBlank()) {
392	                    claimed = claimed.add(claim.getAmount());
393	                }
394	                // A held claim stays in claimed, but leaves the due figures while held.
395	                if (!counts(claim, person, today)) {
396	                    continue;
397	                }
398	                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
399	                if (figure != null) {
400	                    due = due.add(figure);
401	                    if (lateness.overdue(claim)) {
402	                        overdue = overdue.add(figure);
403	                    }
404	                }
405	                // A figure at a grade other than the one in force today, or at a rate that ended before
406	                // today, does not hang on today's grade's rate.
407	                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
408	                        || (figure != null && (!person.gradeOn(claim.getDate()).equals(person.gradeOn(today))
409	                                || rates.forClaim(claim).endsBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), today)));
410	            }
411	            boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
412	            claimedTotal = claimedTotal.add(claimed);
413	            overdues.add(overdue);
414	            due = SettingStore.capped(due, cap);
415	            if (!na) {
416	                dues.add(due);
417	            }
418	            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due),
419	                    shown(overdue)));
420	        }
421	        return new Rollup(figures, shown(claimedTotal), shown(trimmed(dues)), shown(trimmed(overdues)));
422	    }
423	
424	    /** The sum of people's figures, leaving out the single highest and the single lowest when three or more
425	     *  people have one. */
426	    private static BigDecimal trimmed(List<BigDecimal> figures) {
427	        List<BigDecimal> sorted = new ArrayList<>(figures);
428	        sorted.sort(null);
429	        if (sorted.size() >= 3) {
430	            sorted = sorted.subList(1, sorted.size() - 1);
431	        }
432	        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
433	    }
434	
435	    /** Each person's due-total of their claims due by a date in from..to (inclusive) that count by the status they
436	     *  had at the end of {@code to} (see {@link #countsAt}), by person id in the order they were added: the
437	     *  sum of their figures as shown now, skipping n/a, as the screen shows a person's due-total for a
438	     *  period. A period's due-total is the sum of these. */
439	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
440	        LocalDate today = sheets.today(sheetId);
441	        List<Claim> all = claims.list(sheetId);
442	        Lateness lateness = lateness(sheetId, today, all);
443	        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
444	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
445	        for (Person person : people.list(sheetId)) {
446	            BigDecimal total = BigDecimal.ZERO.setScale(2);
447	            for (Claim claim : all) {
448	                if (claim.getPersonId() != person.getId()
449	                        || !countsAt(claim, atEnd.get(claim.getId()), person, today)
450	                        || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
451	                    continue;
452	                }
453	                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
454	                if (figure != null) {
455	                    total = total.add(figure);
456	                }
457	            }
458	            totals.put(person.getId(), total);
459	        }
460	        return totals;
461	    }
462	
463	    /** Each person's figure carried into a period ending on {@code to}, by person id in the order they were added:
464	     *  the sum of the figures (as shown now, skipping n/a) of their claims due by a date in one of the
465	     *  {@code earlier} periods (each from..to, inclusive) that were OPEN or PENDING at the end of {@code to} and
466	     *  count then (see {@link #countsAt}), as the screen shows a person's carried figure for an open period. */
467	    public Map<Long, BigDecimal> carriedByPerson(String sheetId, LocalDate to, List<LocalDate[]> earlier) {
468	        LocalDate today = sheets.today(sheetId);
469	        List<Claim> all = claims.list(sheetId);
470	        Lateness lateness = lateness(sheetId, today, all);
471	        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
472	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
473	        for (Person person : people.list(sheetId)) {
474	            BigDecimal total = BigDecimal.ZERO.setScale(2);
475	            for (Claim claim : all) {
476	                ClaimStatus status = atEnd.get(claim.getId());
477	                if (claim.getPersonId() != person.getId() || status == null || !status.isOpen()
478	                        || !countsAt(claim, status, person, today)
479	                        || earlier.stream().noneMatch(p -> !claim.getDueBy().isBefore(p[0]) && !claim.getDueBy().isAfter(p[1]))) {
480	                    continue;
481	                }
482	                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
483	                if (figure != null) {
484	                    total = total.add(figure);
485	                }
486	            }
487	            totals.put(person.getId(), total);
488	        }
489	        return totals;
490	    }
491	
492	    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
493	    public void record(String sheetId, String user, Rollup before) {
494	        Rollup after = snapshot(sheetId);
495	        String who = " sheet=" + sheetId + " by=" + user;
496	        after.people().forEach((id, now) -> {
497	            if (!now.sameAs(before.people().get(id))) {
498	                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
499	                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
500	            }
501	        });
502	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
503	                || !after.overdueTotal().equals(before.overdueTotal())) {
504	            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
505	                    + " overdue-total=" + after.overdueTotal());
506	        }
507	        alerts(sheetId, who, before, after);
508	    }
509	
510	    /** Records ALERT for each person whose due-total went from at or below the sheet's alert threshold (or none)
511	     *  to above it, in list order; nothing while the threshold is off. */
512	    private void alerts(String sheetId, String who, Rollup before, Rollup after) {
513	        BigDecimal threshold = settings.alertThreshold(sheetId);
514	        if (threshold == null) {
515	            return;
516	        }
517	        after.people().forEach((id, now) -> {
518	            Rollup.Figures was = before == null ? null : before.people().get(id);
519	            if (above(now, threshold) && !above(was, threshold)) {
520	                audit.record("ALERT" + who + " name=" + now.name() + " due-total=" + now.dueTotal());
521	            }
522	        });
523	    }
524	
525	    private static boolean above(Rollup.Figures figures, BigDecimal threshold) {
526	        return figures != null && !NA.equals(figures.dueTotal())
527	                && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
528	    }
529	
530	    /** Records the sheet's figures as they stand, the change made by {@code user}: a ROLLUP line for every
531	     *  person, then its TOTALS, then an ALERT for each person above the alert threshold (each counts as new). */
532	    public void recordAll(String sheetId, String user) {
533	        Rollup now = snapshot(sheetId);
534	        String who = " sheet=" + sheetId + " by=" + user;
535	        now.people().values().forEach(p -> audit.record("ROLLUP" + who + " person=" + p.name() + " claimed="
536	                + p.claimed() + " due-total=" + p.dueTotal() + " overdue-total=" + p.overdueTotal()));
537	        audit.record("TOTALS" + who + " claimed-total=" + now.claimedTotal() + " due-total=" + now.dueTotal()
538	                + " overdue-total=" + now.overdueTotal());
539	        alerts(sheetId, who, null, now);
540	    }
541	
542	    /** What the sheet's late charge follows on the date, for these claims (see {@link Lateness}). */
543	    private Lateness lateness(String sheetId, LocalDate today, List<Claim> all) {
544	        Map<Long, Person> byId = new HashMap<>();
545	        people.list(sheetId).forEach(person -> byId.put(person.getId(), person));
546	        return new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), today,
547	                new Rounding(policyDate(sheetId), settings.roundings(sheetId), all), Lateness.graced(settings.graces(sheetId), byId::get));
548	    }
549	
550	    /** The date the sheet's rounding turns on: the policy date set, else the sheet's today. */
551	    private LocalDate policyDate(String sheetId) {
552	        LocalDate policy = settings.policyDate(sheetId);
553	        return policy != null ? policy : sheets.today(sheetId);
554	    }
555	
556	    /** Only OPEN, PENDING and SETTLED claims count, and an OPEN or PENDING claim of a person whose retirement
557	     *  date the sheet's today has reached does not, unless a statement bound it; nor does an OPEN claim deferred
558	     *  on the sheet's today. A hold (the claim's or its person's) does not take it out: holds only touch cuts. */
559	    public static boolean counts(Claim claim, Person person, LocalDate today) {
560	        return claim.getStatus() == ClaimStatus.SETTLED
561	                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
562	                        && (claim.isStated() || !person.retiredOn(today)));
563	    }
564	
565	    /** Whether the claim counts toward claimed: as {@link #counts}. */
566	    public static boolean countsClaimed(Claim claim, Person person, LocalDate today) {
567	        return claim.getStatus() == ClaimStatus.SETTLED
568	                || (claim.getStatus().isOpen() && !claim.isDeferredOn(today)
569	                        && (claim.isStated() || !person.retiredOn(today)));
570	    }
571	
572	    /** Whether the claim counts by {@code status}, the status it had at a period's end (null when it
573	     *  was added after it): OPEN, PENDING or SETTLED then; and, as the live rules say, an OPEN claim
574	     *  deferred on the sheet's today does not, nor one open then and still open now of a person retired on
575	     *  the sheet's today, unless a statement bound it. */
576	    static boolean countsAt(Claim claim, ClaimStatus status, Person person, LocalDate today) {
577	        return status == ClaimStatus.SETTLED
578	                || (status != null && status.isOpen() && !claim.isDeferredOn(today)
579	                        && (claim.isStated() || !claim.getStatus().isOpen()
580	                                || !person.retiredOn(today)));
581	    }
582	
583	    private static String shown(BigDecimal value) {
584	        return value.setScale(2).toPlainString();
585	    }
586	}
587	package net.officefloor.hq.app.rollup;
588	
589	import net.officefloor.plugin.variable.Out;
590	import org.springframework.web.bind.annotation.PathVariable;
591	
592	/** Takes the sheet's figures before a change, so its audit step can record how the change moved them. */
593	public class SnapshotRollup {
594	    public void snapshot(@PathVariable("sheetId") String sheetId, RollupService rollups, Out<Rollup> before) {
595	        before.set(rollups.snapshot(sheetId.trim()));
596	    }
597	}
