  1	package net.officefloor.hq.app.rollup;
  2	
  3	import java.math.BigDecimal;
  4	import java.time.LocalDate;
  5	import java.util.ArrayList;
  6	import java.util.HashMap;
  7	import java.util.LinkedHashMap;
  8	import java.util.List;
  9	import java.util.Map;
 10	import net.officefloor.hq.app.Audit;
 11	import net.officefloor.hq.app.claim.Claim;
 12	import net.officefloor.hq.app.claim.ClaimLogStore;
 13	import net.officefloor.hq.app.claim.ClaimStatus;
 14	import net.officefloor.hq.app.claim.ClaimStore;
 15	import net.officefloor.hq.app.claim.Lateness;
 16	import net.officefloor.hq.app.claim.Rounding;
 17	import net.officefloor.hq.app.person.Person;
 18	import net.officefloor.hq.app.person.PersonStore;
 19	import net.officefloor.hq.app.rate.RateStore;
 20	import net.officefloor.hq.app.setting.SettingStore;
 21	import net.officefloor.hq.app.sheet.SheetStore;
 22	import org.springframework.stereotype.Service;
 23	
 24	/**
 25	 * Works out the sheet's figures as the screen shows them, and records in the audit file how a change
 26	 * moved them: ROLLUP sheet=<id> by=<user> person=<name> claimed=<0.00> due-total=<0.00 or n/a>
 27	 * overdue-total=<0.00> for each person whose figures changed (a person new to the sheet counts as changed), in
 28	 * list order (by their positions), then TOTALS sheet=<id> by=<user> claimed-total=<0.00> due-total=<0.00>
 29	 * overdue-total=<0.00> when any of the sheet's totals changed; the sheet's due-total and overdue-total leave out
 30	 * the single highest and the single lowest person's figure when three or more people have one (n/a is no figure). A person's overdue-total is the due (late charge
 31	 * included, skipping n/a) of their counting claims that are OPEN or PENDING with a due-by (plus any grace days of their grade, see {@link Lateness}) before today. A person's due-total is at most the sheet's cap. A change that moves no figure records nothing here.
 32	 * After those lines, while the sheet's alert threshold is set, ALERT sheet=<id> by=<user> name=<name> due-total=<0.00>
 33	 * for each person whose due-total the change took from at or below it (or no due-total) to above it, in list order.
 34	 */
 35	@Service
 36	public class RollupService {
 37	
 38	    private static final String NA = "n/a";
 39	
 40	    private final PersonStore people;
 41	    private final ClaimStore claims;
 42	    private final RateStore rates;
 43	    private final SheetStore sheets;
 44	    private final SettingStore settings;
 45	    private final Audit audit;
 46	    private final ClaimLogStore log;
 47	
 48	    public RollupService(PersonStore people, ClaimStore claims, RateStore rates, SheetStore sheets, SettingStore settings,
 49	            Audit audit, ClaimLogStore log) {
 50	        this.people = people;
 51	        this.log = log;
 52	        this.claims = claims;
 53	        this.rates = rates;
 54	        this.sheets = sheets;
 55	        this.settings = settings;
 56	        this.audit = audit;
 57	    }
 58	
 59	    /** The sheet's figures as the store holds them now. */
 60	    public Rollup snapshot(String sheetId) {
 61	        LocalDate today = sheets.today(sheetId);
 62	        List<Claim> all = claims.list(sheetId);
 63	        BigDecimal cap = settings.cap(sheetId);
 64	        Lateness lateness = lateness(sheetId, today, all);
 65	        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
 66	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
 67	        List<BigDecimal> dues = new ArrayList<>();
 68	        List<BigDecimal> overdues = new ArrayList<>();
 69	        for (Person person : people.list(sheetId)) {
 70	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
 71	            BigDecimal due = BigDecimal.ZERO.setScale(2);
 72	            BigDecimal overdue = BigDecimal.ZERO.setScale(2);
 73	            boolean fixed = false;
 74	            for (Claim claim : all) {
 75	                if (claim.getPersonId() != person.getId()
 76	                        || !countsClaimed(claim, person, today)) {
 77	                    continue;
 78	                }
 79	                // A claim that corrects another counts toward due but not toward claimed.
 80	                if (claim.getCorrects() == null || claim.getCorrects().isBlank()) {
 81	                    claimed = claimed.add(claim.getAmount());
 82	                }
 83	                // A held claim stays in claimed, but leaves the due figures while held.
 84	                if (!counts(claim, person, today)) {
 85	                    continue;
 86	                }
 87	                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
 88	                if (figure != null) {
 89	                    due = due.add(figure);
 90	                    if (lateness.overdue(claim)) {
 91	                        overdue = overdue.add(figure);
 92	                    }
 93	                }
 94	                // A figure at a grade other than the one in force today, or at a rate that ended before
 95	                // today, does not hang on today's grade's rate.
 96	                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
 97	                        || (figure != null && (!person.gradeOn(claim.getDate()).equals(person.gradeOn(today))
 98	                                || rates.forClaim(claim).endsBefore(sheetId, person.gradeOn(claim.getDate()), claim.getDate(), today)));
 99	            }
100	            boolean na = rates.find(sheetId, person.gradeOn(today), today) == null && !fixed;
101	            claimedTotal = claimedTotal.add(claimed);
102	            overdues.add(overdue);
103	            due = SettingStore.capped(due, cap);
104	            if (!na) {
105	                dues.add(due);
106	            }
107	            figures.put(person.getId(), new Rollup.Figures(person.getName(), shown(claimed), na ? NA : shown(due),
108	                    shown(overdue)));
109	        }
110	        return new Rollup(figures, shown(claimedTotal), shown(trimmed(dues)), shown(trimmed(overdues)));
111	    }
112	
113	    /** The sum of people's figures, leaving out the single highest and the single lowest when three or more
114	     *  people have one. */
115	    private static BigDecimal trimmed(List<BigDecimal> figures) {
116	        List<BigDecimal> sorted = new ArrayList<>(figures);
117	        sorted.sort(null);
118	        if (sorted.size() >= 3) {
119	            sorted = sorted.subList(1, sorted.size() - 1);
120	        }
121	        return sorted.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
122	    }
123	
124	    /** Each person's due-total of their claims due by a date in from..to (inclusive) that count by the status they
125	     *  had at the end of {@code to} (see {@link #countsAt}), by person id in the order they were added: the
126	     *  sum of their figures as shown now, skipping n/a, as the screen shows a person's due-total for a
127	     *  period. A period's due-total is the sum of these. */
128	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
129	        LocalDate today = sheets.today(sheetId);
130	        List<Claim> all = claims.list(sheetId);
131	        Lateness lateness = lateness(sheetId, today, all);
132	        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
133	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
134	        for (Person person : people.list(sheetId)) {
135	            BigDecimal total = BigDecimal.ZERO.setScale(2);
136	            for (Claim claim : all) {
137	                if (claim.getPersonId() != person.getId()
138	                        || !countsAt(claim, atEnd.get(claim.getId()), person, today)
139	                        || claim.getDueBy().isBefore(from) || claim.getDueBy().isAfter(to)) {
140	                    continue;
141	                }
142	                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
143	                if (figure != null) {
144	                    total = total.add(figure);
145	                }
146	            }
147	            totals.put(person.getId(), total);
148	        }
149	        return totals;
150	    }
151	
152	    /** Each person's figure carried into a period ending on {@code to}, by person id in the order they were added:
153	     *  the sum of the figures (as shown now, skipping n/a) of their claims due by a date in one of the
154	     *  {@code earlier} periods (each from..to, inclusive) that were OPEN or PENDING at the end of {@code to} and
155	     *  count then (see {@link #countsAt}), as the screen shows a person's carried figure for an open period. */
156	    public Map<Long, BigDecimal> carriedByPerson(String sheetId, LocalDate to, List<LocalDate[]> earlier) {
157	        LocalDate today = sheets.today(sheetId);
158	        List<Claim> all = claims.list(sheetId);
159	        Lateness lateness = lateness(sheetId, today, all);
160	        Map<Long, ClaimStatus> atEnd = log.statusesAt(sheetId, to);
161	        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
162	        for (Person person : people.list(sheetId)) {
163	            BigDecimal total = BigDecimal.ZERO.setScale(2);
164	            for (Claim claim : all) {
165	                ClaimStatus status = atEnd.get(claim.getId());
166	                if (claim.getPersonId() != person.getId() || status == null || !status.isOpen()
167	                        || !countsAt(claim, status, person, today)
168	                        || earlier.stream().noneMatch(p -> !claim.getDueBy().isBefore(p[0]) && !claim.getDueBy().isAfter(p[1]))) {
169	                    continue;
170	                }
171	                BigDecimal figure = lateness.due(claim, rates.forClaim(claim).find(sheetId, person.gradeOn(claim.getDate()), claim.getDate()));
172	                if (figure != null) {
173	                    total = total.add(figure);
174	                }
175	            }
176	            totals.put(person.getId(), total);
177	        }
178	        return totals;
179	    }
180	
181	    /** Records how the sheet's figures moved since {@code before}, the change made by {@code user}. */
182	    public void record(String sheetId, String user, Rollup before) {
183	        Rollup after = snapshot(sheetId);
184	        String who = " sheet=" + sheetId + " by=" + user;
185	        after.people().forEach((id, now) -> {
186	            if (!now.sameAs(before.people().get(id))) {
187	                audit.record("ROLLUP" + who + " person=" + now.name() + " claimed=" + now.claimed() + " due-total="
188	                        + now.dueTotal() + " overdue-total=" + now.overdueTotal());
189	            }
190	        });
191	        if (!after.claimedTotal().equals(before.claimedTotal()) || !after.dueTotal().equals(before.dueTotal())
192	                || !after.overdueTotal().equals(before.overdueTotal())) {
193	            audit.record("TOTALS" + who + " claimed-total=" + after.claimedTotal() + " due-total=" + after.dueTotal()
194	                    + " overdue-total=" + after.overdueTotal());
195	        }
196	        alerts(sheetId, who, before, after);
197	    }
198	
199	    /** Records ALERT for each person whose due-total went from at or below the sheet's alert threshold (or none)
200	     *  to above it, in list order; nothing while the threshold is off. */
201	    private void alerts(String sheetId, String who, Rollup before, Rollup after) {
202	        BigDecimal threshold = settings.alertThreshold(sheetId);
203	        if (threshold == null) {
204	            return;
205	        }
206	        after.people().forEach((id, now) -> {
207	            Rollup.Figures was = before == null ? null : before.people().get(id);
208	            if (above(now, threshold) && !above(was, threshold)) {
209	                audit.record("ALERT" + who + " name=" + now.name() + " due-total=" + now.dueTotal());
210	            }
211	        });
212	    }
213	
214	    private static boolean above(Rollup.Figures figures, BigDecimal threshold) {
215	        return figures != null && !NA.equals(figures.dueTotal())
216	                && new BigDecimal(figures.dueTotal()).compareTo(threshold) > 0;
217	    }
218	
219	    /** Records the sheet's figures as they stand, the change made by {@code user}: a ROLLUP line for every
220	     *  person, then its TOTALS, then an ALERT for each person above the alert threshold (each counts as new). */
221	    public void recordAll(String sheetId, String user) {
222	        Rollup now = snapshot(sheetId);
223	        String who = " sheet=" + sheetId + " by=" + user;
224	        now.people().values().forEach(p -> audit.record("ROLLUP" + who + " person=" + p.name() + " claimed="
225	                + p.claimed() + " due-total=" + p.dueTotal() + " overdue-total=" + p.overdueTotal()));
226	        audit.record("TOTALS" + who + " claimed-total=" + now.claimedTotal() + " due-total=" + now.dueTotal()
227	                + " overdue-total=" + now.overdueTotal());
228	        alerts(sheetId, who, null, now);
229	    }
230	
231	    /** What the sheet's late charge follows on the date, for these claims (see {@link Lateness}). */
232	    private Lateness lateness(String sheetId, LocalDate today, List<Claim> all) {
233	        Map<Long, Person> byId = new HashMap<>();
234	        people.list(sheetId).forEach(person -> byId.put(person.getId(), person));
