288	/** What a sheet's late charge follows: each claim's due-by (fixed when it was added), the sheet's late
289	 *  percent in force on each date and its today; and the sheet's floor in force on each claim's date. An overdue claim (OPEN or PENDING, not deferred, due-by before today) gains, for every full 30 days it is
290	 *  overdue, the late percent in force on that boundary (its due-by plus 30, 60, 90 ... days) of its figure plus the
291	 *  charges of the boundaries before it (compounding), each rounded as the sheet's {@link Rounding} has the claim, the charges added up (a boundary at 0.00 adds nothing). A statement binds a claim's due as shown, its
292	 *  charge and floor included: while bound, its charge no longer follows today. Settling freezes it into the settled due. The floor is applied first: a live due is its figure raised to
293	 *  the floor in force on the claim's date (none for a correction), plus the late charge worked out on that floored figure. A claim whose person's grade in force on its date has grace
294	 *  days in force on that date is overdue only when its due-by plus the grace is before today, and its 30-day
295	 *  boundaries count from its due-by plus the grace ({@link #graceBy}). */
296	public record Lateness(Function<LocalDate, BigDecimal> latePcts, Function<LocalDate, BigDecimal> floors,
297	        LocalDate today, Rounding rounding, Function<Claim, LocalDate> graceBy) {
298	
299	    /** The days in each step of the late charge. */
300	    private static final int PERIOD_DAYS = 30;
301	
302	    public static Lateness of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims,
303	            PersonStore people) {
304	        return new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), sheets.today(sheetId),
305	                Rounding.of(sheetId, settings, sheets, claims),
306	                graced(settings.graces(sheetId), id -> people.find(sheetId, id)));
307	    }
308	
309	    /** Each claim's due-by plus the grace days in force on its date for its person's grade then (its due-by
310	     *  when none), given the grace days by grade and date and each person by id. */
311	    public static Function<Claim, LocalDate> graced(BiFunction<String, LocalDate, Integer> graces,
312	            Function<Long, Person> people) {
313	        return claim -> {
314	            Person person = people.apply(claim.getPersonId());
315	            Integer grace = person == null || claim.getDueBy() == null ? null
316	                    : graces.apply(person.gradeOn(claim.getDate()), claim.getDate());
317	            return grace == null ? claim.getDueBy() : claim.getDueBy().plusDays(grace);
318	        };
319	    }
320	
321	    /** Whether the claim is overdue: OPEN (or PENDING), not deferred, with its due-by plus any grace before today. */
322	    public boolean overdue(Claim claim) {
323	        return claim.getStatus().isOpen() && today != null && !claim.isDeferredOn(today) && claim.getDueBy() != null
324	                && graceBy.apply(claim).isBefore(today);
325	    }
326	
327	    /** The late charge on a claim whose floored rate figure is {@code figure}; none on a correction, nor on a
328	     *  claim whose charge was waived, nor on one bound by a statement (its bound due has its charge in it). */
329	    public BigDecimal charge(Claim claim, BigDecimal figure) {
330	        if (figure == null || !claim.getStatus().isOpen() || today == null || claim.isCorrection() || claim.isBound()
331	                || claim.isDeferredOn(today) || claim.isWaived()) {
332	            return BigDecimal.ZERO.setScale(2);
333	        }
334	        LocalDate from = graceBy.apply(claim);
335	        long overdue = ChronoUnit.DAYS.between(from, today);
336	        long periods = overdue <= 0 ? 0 : overdue / PERIOD_DAYS;
337	        BigDecimal total = BigDecimal.ZERO.setScale(2);
338	        for (long n = 1; n <= periods; n++) {
339	            BigDecimal pct = latePcts.apply(from.plusDays(n * PERIOD_DAYS));
340	            total = total.add(ClaimFigure.of(figure.add(total), pct, rounding.mode(claim)));
341	        }
342	        return total;
343	    }
344	
345	    /** The floor in force on the claim's date. */
346	    public BigDecimal floor(Claim claim) {
347	        return floors.apply(claim.getDate());
348	    }
349	
350	    /** The claim's due now: its settled due, else the due its person's last statement bound it to, else the greater
351	     *  of its floor and its figure, plus the late charge worked out on that floored figure (a correction has no floor
352	     *  and no charge). */
353	    public BigDecimal due(Claim claim, BigDecimal pct) {
354	        return dueOf(claim, ClaimFigure.of(claim, pct, rounding));
355	    }
356	
357	    /** The claim's due now, given its figure (see {@link ClaimFigure}). */
358	    public BigDecimal dueOf(Claim claim, BigDecimal figure) {
359	        if (figure == null || claim.getSettledDue() != null || claim.isBound()) {
360	            return figure;
361	        }
362	        BigDecimal floored = claim.isCorrection() ? figure : ClaimFigure.floored(figure, floor(claim));
363	        return floored.add(charge(claim, floored));
364	    }
365	}
