377	/** How a sheet rounds a claim's live figures (its rate step and late charge): a claim dated before the
378	 *  sheet's policy date (the one set, else the sheet's today) rounds half up, one dated on or after it
379	 *  half to even; but a claim whose date has a rounding mode in force (a dated setting) rounds by that mode.
380	 *  A correction rounds by the date of the claim it corrects, not its own. */
381	public final class Rounding {
382	
383	    private final LocalDate policyDate;
384	
385	    /** The rounding mode in force on each date, or null when none is (then the policy date decides). */
386	    private final Function<LocalDate, RoundingMode> modes;
387	
388	    /** The date of each opened claim on the sheet, by its person and number. */
389	    private final Map<String, LocalDate> dates = new HashMap<>();
390	
391	    public Rounding(LocalDate policyDate, List<Claim> claims) {
392	        this(policyDate, date -> null, claims);
393	    }
394	
395	    public Rounding(LocalDate policyDate, Function<LocalDate, RoundingMode> modes, List<Claim> claims) {
396	        this.policyDate = policyDate;
397	        this.modes = modes;
398	        for (Claim claim : claims) {
399	            if (claim.getNumber() != null) {
400	                dates.put(key(claim.getPersonId(), claim.getNumber()), claim.getDate());
401	            }
402	        }
403	    }
404	
405	    /** The sheet's rounding, knowing every claim on it (so a correction finds the claim it corrects). */
406	    public static Rounding of(String sheetId, SettingStore settings, SheetStore sheets, ClaimStore claims) {
407	        LocalDate policy = settings.policyDate(sheetId);
408	        return new Rounding(policy != null ? policy : sheets.today(sheetId), settings.roundings(sheetId),
409	                claims.list(sheetId));
410	    }
411	
412	    /** The date the claim rounds by: its own, or for a correction the date of the claim it corrects. */
413	    public LocalDate date(Claim claim) {
414	        LocalDate date = claim.getDate();
415	        if (claim.getCorrects() != null) {
416	            date = dates.getOrDefault(key(claim.getPersonId(), claim.getCorrects()), date);
417	        }
418	        return date;
419	    }
420	
421	    /** The rounding of the claim's live figures. */
422	    public RoundingMode mode(Claim claim) {
423	        RoundingMode mode = modes.apply(date(claim));
424	        if (mode != null) {
425	            return mode;
426	        }
427	        return policyDate != null && date(claim).isBefore(policyDate) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
428	    }
429	
430	    private static String key(long personId, String number) {
431	        return personId + "/" + number;
432	    }
