252	   252	/** Whether the grade's rate in force on the date among these rates of one sheet ends before `today`. */
253	   253	function ownEndsBefore(rates: Rate[], grade: string, on: string, today: string): boolean {
254	   254	  let best: Rate | undefined;
255	   255	  let next: string | undefined;
256	   256	  for (const r of rates ?? []) {
257	   257	    if (r.grade !== grade) continue;
