270	   270	/** Whole hundredths of a two-decimal number, read exactly from its text. */
271	   271	function hundredths(value: string): bigint {
272	   272	  const [whole, frac = ''] = value.trim().replace(/^-/, '').split('.');
273	   273	  const n = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
