286	   286	  if (pct === undefined) return NA;
287	   287	  // amount (hundredths) × pct (hundredths) is in units of 1/10000 cent-percent: ÷ 10000 gives cents.
288	   288	  const product = hundredths(amount) * hundredths(pct);
289	   289	  const abs = product < 0n ? -product : product;
290	   290	  const rest = abs % 10000n;
291	   291	  let cents = abs / 10000n;
292	   292	  if (rest > 5000n || (rest === 5000n && (halfUp || cents % 2n === 1n))) cents += 1n;
293	   293	  return format(product < 0n ? -cents : cents);
294	   294	}
