312	   312	/** Shares of 100.00 split equally among `count` patrons in the order they were named: each rounded half to
313	   313	 *  even to two decimals, with the remainder (100.00 less the shares added up) given to the first. */
314	   314	export function patronShares(count: number): string[] {
315	   315	  if (count === 0) return [];
