513	   513	/** A preview of a candidate percent for a grade: of these people's OPEN and PENDING claims whose person
514	   514	 *  was on the grade on the claim's date, how many would show a different due were the candidate the
515	   515	 *  grade's only rate (from the beginning of time, no end), and the sum of new due less current due (n/a
516	   516	 *  as 0.00). A claim bound by a statement or settled keeps its figure. Nothing is saved. */
517	   517	export function ratePreview(
518	   518	  people: { grades: Grades; claims: Claim[]; late?: Late }[],
519	   519	  rates: Rate[] | undefined,
520	   520	  grade: string,
521	   521	  pct: string,
522	   522	  floor: Floor,
523	   523	): { count: number; diff: string } {
524	   524	  const candidate: Rate[] = [...(rates ?? []).filter((r) => r.grade !== grade || (r.level ?? 0) > 0), { grade, pct, from: null, to: null }];
525	   525	  const figure = (d: string) => (d === NA ? 0n : hundredths(d));
526	   526	  let count = 0;
527	   527	  let diff = 0n;
528	   528	  for (const p of people) {
529	   529	    for (const c of p.claims) {
530	   530	      if (c.status !== 'OPEN' && c.status !== 'PENDING') continue;
531	   531	      if (gradeOn(p.grades, c.date) !== grade) continue;
532	   532	      const now = claimDue(c, rates, p.grades, floor, p.late);
533	   533	      const then = claimDue(c, candidate, p.grades, floor, p.late);
534	   534	      if (now === then) continue;
535	   535	      count += 1;
536	   536	      diff += figure(then) - figure(now);
537	   537	    }
538	   538	  }
539	   539	  return { count, diff: format(diff) };
