16:/** Works out the move a status change makes. Opening a DRAFT whose due is above the review threshold in
17: *  force on its date sends it to REVIEW instead; only a steward's review moves a REVIEW claim on, to OPEN,
18: *  and otherwise it may only be voided. A clerk settling an OPEN claim whose due is above the
19: *  sheet's clerk limit sends it to PENDING instead. A claim whose due is n/a is within any limit; a
20: *  sheet with no limit, and a steward, settle anything. Only a steward, or the claim's person's approver, reviews a PENDING claim, and
21: *  only a review moves it to SETTLED or back to OPEN; a review of a claim that is not PENDING is refused.
22: *  Before the limit is considered, settling or approving a claim with no proofs whose due is above the
23: *  proof threshold is refused (see {@link CheckProofs}), so it never goes to PENDING. Opening, settling
24: *  and voiding are refused to a role the sheet's permission matrix does not allow it, and opening
25: *  a claim of a person whose flag is in force on the sheet's today to anyone but a steward. A SETTLED claim
26: *  may be voided only by a steward, and only within {@link #VOID_SETTLED_DAYS} days of the sheet's today
27: *  it was settled on (its status log's SETTLED date). A DELETED claim may be restored only on the
28: *  sheet's today it was deleted on. */
29:public class CheckClerkLimit {
30:    /** How many days after settling a claim a steward may still void it. */
31:    static final int VOID_SETTLED_DAYS = 7;
33:    public void check(@Val StatusInput input, @Val Claim claim, RoleStore roles, SettingStore settings,
34:            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims, ClaimLogStore log,
35:            Out<StatusMove> move)
36:            throws InvalidSheetException {
37:        ClaimStatus from = claim.getStatus();
38:        Role role = roles.find(claim.getSheetId(), input.user());
39:        boolean steward = role == Role.STEWARD;
40:        if (input.review() && from == ClaimStatus.REVIEW) {
41:            if (!steward) {
42:                throw new InvalidSheetException("Only a steward can review a claim");
43:            }
44:            if (input.status() != ClaimStatus.OPEN) {
45:                throw new InvalidSheetException("A review makes a REVIEW claim OPEN");
46:            }
47:            move.set(new StatusMove(from, ClaimStatus.OPEN));
48:            return;
49:        }
50:        if (input.review()) {
51:            if (from != ClaimStatus.PENDING) {
52:                throw new InvalidSheetException("Only a PENDING claim can be approved or rejected");
53:            }
54:            if (!steward && !approver(claim, input.user(), people)) {
55:                throw new InvalidSheetException("Only a steward or the person's approver can approve or reject a claim");
56:            }
57:            if (input.status() == ClaimStatus.OPEN && input.reason().isEmpty()) {
58:                throw new InvalidSheetException("A rejection needs a reason");
59:            }
60:            CheckProofs.refuseUnproved(input, claim, settings, people, rates, sheets, claims);
61:            move.set(new StatusMove(from, input.status()));
62:            return;
63:        }
64:        if (from == ClaimStatus.PENDING && input.status() != ClaimStatus.VOID) {
65:            throw new InvalidSheetException("A PENDING claim waits for a steward to approve or reject it");
66:        }
67:        if (from == ClaimStatus.REVIEW && input.status() != ClaimStatus.VOID) {
68:            throw new InvalidSheetException("A REVIEW claim waits for a steward to review it");
69:        }
70:        refuseUnpermitted(input.status(), claim.getSheetId(), role, settings);
71:        if (from == ClaimStatus.SETTLED && input.status() == ClaimStatus.VOID) {
72:            refuseLateVoid(claim, steward, log, sheets);
73:        }
74:        if (from == ClaimStatus.DELETED && input.status() == ClaimStatus.DRAFT) {
75:            refuseLateRestore(claim, log, sheets);
76:        }
77:        if (from == ClaimStatus.DRAFT && input.status() == ClaimStatus.OPEN) {
