91:    /** Whether opening the claim sends it to REVIEW: its due is above the review threshold in force on its
92:     *  date. A sheet with no threshold then, and a claim whose due is n/a, open as OPEN. */
93:    static boolean overReview(Claim claim, SettingStore settings, PersonStore people, RateStore rates,
94:            SheetStore sheets, ClaimStore claims) {
95:        BigDecimal threshold = settings.reviewThreshold(claim.getSheetId(), claim.getDate());
96:        if (threshold == null) {
97:            return false;
98:        }
99:        Person person = people.find(claim.getSheetId(), claim.getPersonId());
100:        BigDecimal pct = person == null ? null : rates.forClaim(claim).find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
101:        BigDecimal due = Lateness.of(claim.getSheetId(), settings, sheets, claims, people).due(claim, pct);
102:        return due != null && due.compareTo(threshold) > 0;
