107:    static void refuseLateVoid(Claim claim, boolean steward, ClaimLogStore log, SheetStore sheets)
108:            throws InvalidSheetException {
109:        if (!steward) {
110:            throw new InvalidSheetException("Only a steward can void a SETTLED claim");
111:        }
112:        LocalDate settled = log.settledOn(claim);
113:        LocalDate today = sheets.today(claim.getSheetId());
114:        if (settled == null || today == null || today.isAfter(settled.plusDays(VOID_SETTLED_DAYS))) {
115:            throw new InvalidSheetException("A SETTLED claim can be voided only within " + VOID_SETTLED_DAYS
116:                    + " days of settling it");
117:        }
118:    }
