123:        LocalDate deleted = log.lastOn(claim, ClaimStatus.DELETED);
124:        LocalDate today = sheets.today(claim.getSheetId());
125:        if (deleted == null || today == null || !today.equals(deleted)) {
126:            throw new InvalidSheetException("A DELETED claim can be restored only on the day it was deleted");
127:        }
128:    }
