145:    /** Whether the claim's person has a flag in force on the sheet's today. */
146:    static boolean flagged(Claim claim, PersonStore people, SheetStore sheets) {
147:        Person person = people.find(claim.getSheetId(), claim.getPersonId());
148:        return person != null && person.flaggedOn(sheets.today(claim.getSheetId()));
149:    }
151:    /** Refuses opening, settling or voiding a claim by a role the sheet's permission matrix does not allow it. */
152:    static void refuseUnpermitted(ClaimStatus to, String sheetId, Role role, SettingStore settings)
153:            throws InvalidSheetException {
154:        String action = to == ClaimStatus.OPEN ? "open" : to == ClaimStatus.SETTLED ? "settle"
155:                : to == ClaimStatus.VOID ? "void" : null;
