157:            throw new InvalidSheetException("A " + role.shown() + " may not " + action + " a claim");
158:        }
159:    }
161:    static boolean overLimit(StatusInput input, Claim claim, boolean steward, SettingStore settings,
162:            PersonStore people, RateStore rates, SheetStore sheets, ClaimStore claims) {
