26:        }
27:        Person person = people.find(claim.getSheetId(), claim.getPersonId());
28:        String grade = person == null ? null : person.gradeOn(claim.getDate());
29:        BigDecimal threshold = settings.proofThreshold(claim.getSheetId(), grade, claim.getDate());
30:        if (threshold == null) {
