 15	/** Whether the claim is overdue: it is OPEN (or PENDING), not deferred, and its due-by plus any grace is before the sheet's today. */
 16	export function overdue(claim: Claim, today: string | undefined, late?: Late): boolean {
 17	  return isOpen(claim) && !claim.deferred && today !== undefined && graceBy(claim, late) < today;
 18	}
