 20	/** The date `days` after the date (yyyy-MM-dd). */
 21	const plusDays = (date: string, days: number): string =>
 22	  new Date(Date.parse(`${date}T00:00:00Z`) + days * DAY).toISOString().slice(0, 10);
 23	
 24	/** Whether the claim is review-late: it is REVIEW and its review day plus the sheet's review SLA (whole days; null or
 25	 *  blank for none) is before the sheet's today. */
 26	export function reviewLate(claim: Claim, today: string | undefined, sla: string | null | undefined): boolean {
 27	  return claim.status === 'REVIEW' && claim.reviewOn !== null && today !== undefined && sla != null && sla !== ''
 28	    && plusDays(claim.reviewOn, Number(sla)) < today;
 29	}
