 31	/** How many full 30 days the claim is overdue on the sheet's today, counted from its due-by plus any grace (0 when it is not overdue). */
 32	export function latePeriods(claim: Claim, today: string | undefined, late?: Late): number {
 33	  if (today === undefined || !overdue(claim, today, late)) return 0;
 34	  const days = (Date.parse(`${today}T00:00:00Z`) - Date.parse(`${graceBy(claim, late)}T00:00:00Z`)) / DAY;
 35	  return Math.floor(days / 30);
 36	}
