 38	/** The 30-day boundaries (yyyy-MM-dd) the claim is overdue past on the sheet's today: its due-by plus any grace, plus 30, 60, 90 ... days. */
 39	export function lateBoundaries(claim: Claim, today: string | undefined, late?: Late): string[] {
 40	  const start = Date.parse(`${graceBy(claim, late)}T00:00:00Z`);
 41	  return Array.from({ length: latePeriods(claim, today, late) }, (_, i) =>
 42	    new Date(start + (i + 1) * 30 * DAY).toISOString().slice(0, 10));
 43	}
