 45	/** What the sheet's late charge follows: its late percent in force on each boundary date, each claim's due-by plus
 46	 *  the grace days in force on its date for its person's grade then (of these people), and its today; and how it rounds:
 47	 *  a claim rounding by a date with a rounding mode in force rounds by it, else one rounding by a date before the policy
 48	 *  date (else the sheet's today) rounds half up. */
 49	export function lateOf(settings: Settings | undefined, today: string | undefined, people: Person[] | undefined): Late {
 50	  const policy = settings?.policyDate ?? today;
 51	  const pcts = latePctOf(settings);
 52	  const roundings = roundingOf(settings);
 53	  const graces = graceOf(settings);
 54	  const late: Late = {
 55	    pct: pcts,
 56	    boundaries: (c) => lateBoundaries(c, today, late),
 57	    halfUp: (c) => {
 58	      const mode = roundings?.(c.roundsBy ?? c.date);
 59	      if (mode === 'half-up' || mode === 'half-even') return mode === 'half-up';
 60	      return policy !== undefined && (c.roundsBy ?? c.date) < policy;
 61	    },
 62	    graceBy: (c) => {
 63	      const person = people?.find((p) => p.id === c.personId);
 64	      const grace = person && graces?.(gradeOn(person.grades, c.date), c.date);
 65	      return grace == null ? dueBy(c) : plusDays(dueBy(c), grace);
 66	    },
 67	  };
 68	  return late;
 69	}
