142	/** The value in force on the date: the one with the latest from-date on or before it, else `starting`. */
143	export function valueOn(history: Dated[], date: string, starting: string): string {
144	  let found: string | null = null;
145	  for (const d of history) if (d.from <= date) found = d.value;
146	  return found ?? starting;
147	}
