149	/** The floor in force on each date; undefined until the settings are read. */
150	export function floorOf(settings: Settings | undefined): ((date: string) => string) | undefined {
151	  return settings && ((date) => valueOn(settings.floorFrom, date, STARTING_FLOOR));
152	}
153	
154	/** The late percent in force on each date; undefined until the settings are read. */
155	export function latePctOf(settings: Settings | undefined): ((date: string) => string) | undefined {
156	  return settings && ((date) => valueOn(settings.latePctFrom, date, STARTING_LATE_PCT));
157	}
