159	/** The rounding mode in force on each date ('half-up', 'half-even', or '' for none); undefined until the settings are read. */
160	export function roundingOf(settings: Settings | undefined): ((date: string) => string) | undefined {
161	  return settings && ((date) => valueOn(settings.roundingFrom ?? [], date, ''));
162	}
