164	/** The grace days of a grade in force on each date (null for none); undefined until the settings are read. */
165	export function graceOf(settings: Settings | undefined): ((grade: string, date: string) => number | null) | undefined {
166	  return settings && ((grade, date) => {
167	    const value = valueOn(settings.gradeGraceFrom?.[grade] ?? [], date, '');
168	    return value === '' ? null : Number(value);
169	  });
170	}
