   221	            case PENDING -> this == OPEN;
   222	            case SETTLED -> this == OPEN || this == PENDING;
   223	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
   224	            case DELETED -> this == DRAFT;
   225	            case DRAFT -> this == DELETED;
   226	            case REVIEW -> this == DRAFT;
   227	        };
   228	    }
