14:/** Splits the amount off the OPEN claim, which keeps the rest unbound from any statement figure, into a new
15: *  OPEN claim of the same date and note, numbered next in the period of its own due-by (see {@link Numbering}), opened by the user, due by
16: *  the business day its person's own terms (else the grade's they have, else the sheet's, each in force on the sheet's today, when it is split off) after its date, fixed
17: *  now (a late entry when the period that due-by falls in is soft-closed), and logged as OPEN by the user. Refused when another user moved the claim on first. */
18:public class ApplySplit {
19:    public void apply(@Val SplitInput input, @Val Claim claim, ClaimStore store, PersonStore people, SettingStore settings,
20:            SheetStore sheets, PeriodStore periods, ClaimLogStore log, HolidayStore holidays,
21:            Out<Split> split) throws InvalidSheetException {
22:        if (!store.shrink(claim, claim.getAmount().subtract(input.amount()))) {
23:            throw new InvalidSheetException("Only an OPEN claim can be split");
24:        }
25:        String sheetId = claim.getSheetId();
26:        Person person = people.find(sheetId, claim.getPersonId());
27:        int terms = SaveClaimAdded.termsOf(person, settings);
28:        LocalDate dueBy = holidays.businessDaysAfter(sheetId, claim.getDate(), terms);
29:        String number = Numbering.next(sheetId, dueBy, store, settings, sheets, periods);
30:        Claim into = store.addSplit(claim, input.amount(), number, input.user(), dueBy, terms);
31:        if (periods.softOn(sheetId, dueBy)) {
32:            store.markLateEntry(into);
33:        }
34:        log.record(into, input.user());
35:        split.set(new Split(into));
36:    }
