    26	    @Override
    27	    protected boolean shouldNotFilter(HttpServletRequest request) {
    28	        return !request.getRequestURI().startsWith("/api/") || request.getRequestURI().endsWith("/locale")
    29	                || "GET".equals(request.getMethod())
