    20	    /** A table expression, named as the table, for use in place of it in a query's FROM: the table's rows
    21	     *  (each identified by {@code keys}, comma separated) as they stood at the end of {@code date}. */
    22	    public static String asOf(String table, String keys, LocalDate date) {
    23	        String on = "DATE '" + date + "'";
    24	        String same = Arrays.stream(keys.split(",")).map(String::trim).map(k -> "l." + k + " = h." + k)
    25	                .collect(Collectors.joining(" AND "));
    26	        return "(SELECT h.* FROM " + table + "_hist h WHERE h.hist_made_on <= " + on + " AND NOT EXISTS (SELECT 1 FROM "
    27	                + table + "_hist l WHERE " + same + " AND l.hist_made_on <= " + on + " AND l.hist_seq > h.hist_seq) AND NOT h.hist_gone) "
    28	                + table;
