    13	/** Keeps every version of a row of the table it is set on in {@code <table>_hist}: after each insert or
    14	 *  update the new row, after a delete the old one marked gone, each with the sheet's today when the change
    15	 *  was made (the real date when the sheet has none set) and the next {@code hist_seq}. See {@link History}. */
    16	public class HistoryTrigger implements Trigger {
    17	
    18	    private String insert;
    19	
    20	    private int columns;
    21	
    22	    private int sheetColumn;
    23	
    24	    @Override
    25	    public void init(Connection conn, String schemaName, String triggerName, String tableName, boolean before,
    26	            int type) throws SQLException {
    27	        List<String> names = new ArrayList<>();
    28	        try (ResultSet rs = conn.getMetaData().getColumns(null, schemaName, tableName, null)) {
    29	            while (rs.next()) {
    30	                names.add(rs.getString("COLUMN_NAME"));
    31	            }
    32	        }
    33	        columns = names.size();
    34	        sheetColumn = names.indexOf("SHEET_ID");
    35	        StringBuilder sql = new StringBuilder("INSERT INTO \"" + schemaName + "\".\"" + tableName
    36	                + "_HIST\" (HIST_SEQ, HIST_MADE_ON, HIST_GONE");
    37	        for (String name : names) {
    38	            sql.append(", \"").append(name).append('"');
    39	        }
    40	        sql.append(") VALUES (NEXT VALUE FOR \"").append(schemaName).append("\".HIST_SEQ, ?, ?");
    41	        sql.append(", ?".repeat(columns)).append(')');
    42	        insert = sql.toString();
    43	    }
    44	
    45	    @Override
    46	    public void fire(Connection conn, Object[] oldRow, Object[] newRow) throws SQLException {
    47	        Object[] row = newRow != null ? newRow : oldRow;
    48	        try (PreparedStatement ps = conn.prepareStatement(insert)) {
    49	            ps.setDate(1, Date.valueOf(today(conn, row[sheetColumn])));
    50	            ps.setBoolean(2, newRow == null);
    51	            for (int i = 0; i < columns; i++) {
    52	                ps.setObject(i + 3, row[i]);
    53	            }
    54	            ps.executeUpdate();
    55	        }
    56	    }
    57	
    58	    /** The sheet's today, as {@code SheetStore} reads it. */
    59	    private static LocalDate today(Connection conn, Object sheetId) throws SQLException {
    60	        try (PreparedStatement ps = conn.prepareStatement("SELECT today FROM sheet WHERE id = ?")) {
    61	            ps.setObject(1, sheetId);
    62	            try (ResultSet rs = ps.executeQuery()) {
    63	                return rs.next() ? rs.getObject(1, LocalDate.class) : LocalDate.now();
    64	            }
    65	        }
    66	    }
    67	}

