 28	/** Whether the period's figures are fixed: it is closed or soft-closed. */
 29	export const isFixed = (period: Period) => period.closed || period.soft;
 30	
 31	/** Under the sheet's key, so loading the sheet again re-reads its periods. */
 32	export const periodsKey = (sheet: string) => [...sheetKey(sheet), 'periods'] as const;
 33	
 34	/** Every period on the sheet, by from-date. */
 35	export function usePeriods(sheet: string) {
 36	  const [asOf] = useAsOf();
 37	  return useQuery({
 38	    queryKey: asOfKey(periodsKey(sheet), asOf),
 39	    queryFn: () => getJson<Period[]>(asOfPath(`/api/sheets/${encodeURIComponent(sheet)}/periods`, asOf)),
 40	    enabled: sheet !== '',
 41	  });
 42	}
