 44	/** Whether the date (yyyy-MM-dd) falls in the period. */
 45	export const contains = (period: Period, date: string) => period.from <= date && date <= period.to;
 46	
 47	/** The period whose dates contain the date, or undefined when none does. */
 48	export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
 49	  return (periods ?? []).find((p) => contains(p, date));
 50	}
 51	
 52	/** The claim's status at the end of the day (yyyy-MM-dd), as its status log records it (each line
 53	 *  dated the sheet's today when the change was made); null when it had not been added by then. */
 54	export function statusAt(claim: Claim, date: string): ClaimStatus | null {
 55	  let status: ClaimStatus | null = null;
 56	  for (const line of claim.log ?? []) {
 57	    const m = /^(\S+) by .* on (\d{4}-\d{2}-\d{2}) due=/.exec(line);
 58	    if (m && m[2] <= date) status = m[1] as ClaimStatus;
 59	  }
 60	  return status;
 61	}
