 63	/** Whether the claim counts toward a period: by the status it had at the end of the period's last
 64	 *  day it was OPEN, PENDING or SETTLED; and, as the live rules say, it is not deferred on the sheet's
 65	 *  today, nor (while open then and still open now, and unbound by a statement) of a person whose retirement date the sheet's today has reached. */
 66	export function countsInPeriod(claim: Claim, period: Period, person: Person): boolean {
 67	  const status = statusAt(claim, period.to);
 68	  if (status === 'SETTLED') return true;
 69	  if (status !== 'OPEN' && status !== 'PENDING') return false;
 70	  return !(claim.status !== 'VOID' && claim.deferred) && (claim.stated || !isOpen(claim) || !person.retiredNow);
 71	}
