 76	export function personPeriodDue(
 77	  period: Period,
 78	  person: Person,
 79	  claims: Claim[] | undefined,
 80	  rates: Rate[] | undefined,
 81	  floor: Floor,
 82	  late: Late,
 83	): string {
 84	  if (isFixed(period)) return period.people?.[String(person.id)] ?? '0.00';
 85	  return dueTotal(
 86	    (claims ?? [])
 87	      .filter((c) => c.personId === person.id && contains(period, c.dueBy) && countsInPeriod(c, period, person))
 88	      .map((c) => claimDue(c, rates, person.grades, floor, late)),
