 97	export function personPeriodCarried(
 98	  period: Period,
 99	  periods: Period[] | undefined,
100	  person: Person,
101	  claims: Claim[] | undefined,
102	  rates: Rate[] | undefined,
103	  floor: Floor,
104	  late: Late,
105	  opening: string,
106	): string {
107	  if (isFixed(period)) return period.carried?.[String(person.id)] ?? '0.00';
108	  const earlier = (periods ?? []).filter((p) => p.to < period.from);
109	  return dueTotal([
110	    opening,
111	    ...(claims ?? [])
112	      .filter((c) => c.personId === person.id && earlier.some((p) => contains(p, c.dueBy)))
113	      .filter((c) => {
114	        const status = statusAt(c, period.to);
115	        return (status === 'OPEN' || status === 'PENDING') && countsInPeriod(c, period, person);
116	      })
117	      .map((c) => claimDue(c, rates, person.grades, floor, late)),
118	  ]);
119	}
