9:/** The number a claim receives when opened. While the sheet's period-numbering-from is set and the
10: *  sheet's today is on or after it, the claim is numbered within the period its due-by falls in,
11: *  <period name>-<n> counting from 1 in each period, or X-<n> in its own sequence when it falls in
12: *  none. Otherwise it takes the next sheet-wide number of the fiscal year its due-by falls in (by the
13: *  sheet's fiscal start month), FY<yyyy>-<n> counting from 1 in each fiscal year, the sequence all
14: *  the sheets of its tree share: one after the last number given in that fiscal year on any of them.
15: *  Numbers given before (1, 2, ...) stay as they are. */
16:public final class Numbering {
18:    /** The sequence of claims due by a date in no period. */
19:    private static final String NO_PERIOD = "X";
21:    private Numbering() {
22:    }
24:    public static String next(String sheetId, LocalDate dueBy, ClaimStore claims, SettingStore settings,
25:            SheetStore sheets, PeriodStore periods) {
26:        LocalDate from = settings.periodNumberingFrom(sheetId);
27:        if (from == null || sheets.today(sheetId).isBefore(from)) {
28:            LocalDate on = dueBy == null ? sheets.today(sheetId) : dueBy;
29:            int startMonth = settings.fiscalStartMonth(sheetId);
30:            int year = on.getMonthValue() >= startMonth ? on.getYear() : on.getYear() - 1;
31:            return "FY" + year + "-" + claims.nextFiscalNumber(sheetId, settings.wholeTree(sheetId), year);
32:        }
33:        PeriodResponse period = periods.on(sheetId, dueBy);
34:        if (period == null) {
35:            return NO_PERIOD + "-" + claims.nextNumber(sheetId, NO_PERIOD);
36:        }
37:        return period.name() + "-" + claims.nextNumber(sheetId, "P:" + period.name());
38:    }
39:}
