    11	public final class PeriodClosing {
    12	
    13	    private PeriodClosing() {
    14	    }
    15	
    16	    /** Closes the open (or soft-closed) period, fixing its due-total and each person's due-total and carried figure in it
    17	     *  (with their opening balance for it added)
    18	     *  as they are now; refused when it was closed meanwhile. Shared by a close by hand and the auto close of a new today. */
    19	    public static PeriodResponse fix(String sheet, PeriodResponse period, PeriodStore store, RollupService rollups)
    20	            throws InvalidSheetException {
    21	        return fix(sheet, period, store, rollups, false);
    22	    }
    23	
    24	    /** Soft-closes the open period, fixing its figures as {@link #fix} does while leaving its claims open
    25	     *  to change; refused when it was closed or soft-closed meanwhile. */
    26	    public static PeriodResponse fixSoft(String sheet, PeriodResponse period, PeriodStore store, RollupService rollups)
    27	            throws InvalidSheetException {
    28	        return fix(sheet, period, store, rollups, true);
    29	    }
    30	
    31	    private static PeriodResponse fix(String sheet, PeriodResponse period, PeriodStore store, RollupService rollups,
    32	            boolean soft) throws InvalidSheetException {
    33	        LocalDate from = LocalDate.parse(period.from());
    34	        LocalDate to = LocalDate.parse(period.to());
    35	        Map<Long, BigDecimal> people = rollups.dueBetweenByPerson(sheet, from, to);
    36	        List<LocalDate[]> earlier = store.list(sheet).stream().filter(p -> LocalDate.parse(p.to()).isBefore(from))
    37	                .map(p -> new LocalDate[] { LocalDate.parse(p.from()), LocalDate.parse(p.to()) }).toList();
    38	        Map<Long, BigDecimal> carried = rollups.carriedByPerson(sheet, to, earlier);
    39	        store.openings(sheet, period.name()).forEach((id, amount) -> carried.merge(id, amount, BigDecimal::add));
    40	        BigDecimal total = people.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    41	        if (!(soft ? store.softClose(sheet, period.name(), total) : store.close(sheet, period.name(), total))) {
    42	            throw new InvalidSheetException("The period " + period.name() + " is already closed");
    43	        }
    44	        store.dropPersonTotals(sheet, period.name());
    45	        store.fixPersonTotals(sheet, period.name(), people, carried);
    46	        return PeriodResponse.of(period.name(), from, to, !soft, total, people, soft, period.cap(), carried,
    47	                period.locked());
    48	    }
    49	}
