    31	    private static PeriodResponse fix(String sheet, PeriodResponse period, PeriodStore store, RollupService rollups,
    32	            boolean soft) throws InvalidSheetException {
    33	        LocalDate from = LocalDate.parse(period.from());
    34	        LocalDate to = LocalDate.parse(period.to());
    35	        Map<Long, BigDecimal> people = rollups.dueBetweenByPerson(sheet, from, to);
    36	        List<LocalDate[]> earlier = store.list(sheet).stream().filter(p -> LocalDate.parse(p.to()).isBefore(from))
    37	                .map(p -> new LocalDate[] { LocalDate.parse(p.from()), LocalDate.parse(p.to()) }).toList();
    38	        Map<Long, BigDecimal> carried = rollups.carriedByPerson(sheet, to, earlier);
    39	        store.openings(sheet, period.name()).forEach((id, amount) -> carried.merge(id, amount, BigDecimal::add));
    40	        BigDecimal total = people.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
