=== SettleClaims
30:/** Settles each selected claim, in list order: its people by their positions, a person's
31: *  claims newest first. Each goes through the very steps of a single settle by the user (period,
32: *  clerk limit, opened-by, edited-by and status checks, then store, log and audit), so a clerk's settle above
33: *  the clerk limit sends it to PENDING, which counts as settled. A claim that is not on the sheet,
34: *  or that a single settle would refuse (every claim on an archived sheet), is refused.
35: *  All or nothing: when any is refused, none is settled, every one counts as refused and nothing is
36: *  stored or audited. Otherwise the bulk settle takes the sheet's next batch, each settled claim records
37: *  it, and after the claims' own records BATCH_SETTLED sheet=<id> by=<user> batch=<n> count=<claims>
38: *  total=<the frozen figures of those SETTLED, added up> is written. */
39:public class SettleClaims {
40:    public void settle(@PathVariable("sheetId") String sheetId, @Val BulkSettleInput input, ClaimStore store,
41:            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles,
42:            RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, WatchStore watches,
43:            VoidReasonStore voidReasons, PlatformTransactionManager transactions,
44:            Out<BulkSettleResult> result) {
45:        String sheet = sheetId.trim();
46:        Map<Long, Integer> personOrder = new HashMap<>();
47:        // A person's claims newest first, as listed: a claim moved to them is listed as their newest.
48:        Map<Long, Integer> listed = new HashMap<>();
49:        for (Claim claim : store.list(sheet)) {
50:            listed.put(claim.getId(), listed.size());
51:        }
52:        for (Person person : people.list(sheet)) {
53:            personOrder.put(person.getId(), personOrder.size());
54:        }
55:        int refused = 0;
56:        List<Claim> selected = new ArrayList<>();
57:        for (Long id : input.claimIds()) {
58:            Claim claim = id == null ? null : store.find(sheet, id);
59:            if (claim == null) {
60:                refused++;
61:            } else {
62:                selected.add(claim);
63:            }
64:        }
65:        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
66:                .thenComparing(c -> listed.getOrDefault(c.getId(), Integer.MAX_VALUE)));
67:        StatusInput status = new StatusInput(ClaimStatus.SETTLED, input.user(), false, "");
68:        int all = input.claimIds().size();
69:        if (refused > 0) {
70:            result.set(new BulkSettleResult(0, all));
71:            return;
72:        }
73:        // All or nothing: the claims are settled in a nested transaction, their audit records held back,
74:        // and the first refusal rolls every one of them back and drops the records.
75:        TransactionTemplate nested = new TransactionTemplate(transactions);
76:        nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
77:        audit.hold();
78:        boolean done = false;
79:        try {
80:            done = Boolean.TRUE.equals(nested.execute(tx -> {
81:                long batch = store.nextBatch(sheet);
82:                BigDecimal total = BigDecimal.ZERO;
83:                for (Claim claim : selected) {
84:                    try {
85:                        sheets.refuseArchived(sheet);
86:                        new CheckClaimPeriod().check(claim, periods);
87:                        StatusMove[] move = new StatusMove[1];
88:                        new CheckClerkLimit().check(status, claim, roles, settings, people, rates, sheets, store, log,
89:                                m -> move[0] = m);
90:                        Rollup before = rollups.snapshot(sheet);
91:                        StatusChange[] change = new StatusChange[1];
92:                        new ApplyStatus().apply(status, move[0], claim, store, people, rates, settings, sheets, periods,
93:                                voidReasons, c -> change[0] = c);
94:                        new SaveClaim().save(status, claim, store, log);
95:                        store.markBatch(claim, batch);
96:                        new AuditClaimStatus().audit(status, move[0], claim, change[0], before, people, audit, rollups,
97:                                watches);
98:                        if (move[0].to() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
99:                            total = total.add(claim.getSettledDue());
100:                        }
101:                    } catch (InvalidSheetException e) {
102:                        tx.setRollbackOnly();
103:                        return false;
104:                    }
105:                }
106:                audit.record("BATCH_SETTLED sheet=" + sheet + " by=" + input.user() + " batch=" + batch + " count="
107:                        + selected.size() + " total=" + total.setScale(2, RoundingMode.HALF_UP).toPlainString());
108:                return true;
109:            }));
110:        } finally {
111:            if (done) {
112:                audit.release();
113:            } else {
114:                audit.discard();
115:            }
116:        }
117:        result.set(done ? new BulkSettleResult(selected.size(), 0) : new BulkSettleResult(0, all));
118:    }
119:}

