34:public class VoidClaims {
35:    public void voidClaims(@PathVariable("sheetId") String sheetId, @Val BulkVoidInput input, ClaimStore store,
36:            PersonStore people, PeriodStore periods, SettingStore settings, SheetStore sheets, RoleStore roles,
37:            RateStore rates, ClaimLogStore log, RollupService rollups, Audit audit, WatchStore watches,
38:            VoidReasonStore voidReasons, PlatformTransactionManager transactions,
39:            Out<BulkVoidResult> result) {
40:        String sheet = sheetId.trim();
41:        Map<Long, Integer> personOrder = new HashMap<>();
42:        // A person's claims newest first, as listed: a claim moved to them is listed as their newest.
43:        Map<Long, Integer> listed = new HashMap<>();
44:        for (Claim claim : store.list(sheet)) {
45:            listed.put(claim.getId(), listed.size());
46:        }
47:        for (Person person : people.list(sheet)) {
48:            personOrder.put(person.getId(), personOrder.size());
49:        }
50:        int refused = 0;
51:        List<Claim> selected = new ArrayList<>();
52:        for (Long id : input.claimIds()) {
53:            Claim claim = id == null ? null : store.find(sheet, id);
54:            if (claim == null) {
55:                refused++;
56:            } else {
57:                selected.add(claim);
58:            }
59:        }
60:        selected.sort(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
61:                .thenComparing(c -> listed.getOrDefault(c.getId(), Integer.MAX_VALUE)));
62:        StatusInput status = new StatusInput(ClaimStatus.VOID, input.user(), false, input.reason());
63:        TransactionTemplate nested = new TransactionTemplate(transactions);
64:        nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
65:        int voided = 0;
66:        for (Claim claim : selected) {
67:            audit.hold();
68:            boolean done = false;
69:            try {
70:                done = Boolean.TRUE.equals(nested.execute(tx -> {
71:                    try {
72:                        roles.refuseChange(sheet, input.user());
73:                        new CheckClaimPeriod().check(claim, periods);
74:                        StatusMove[] move = new StatusMove[1];
75:                        new CheckClerkLimit().check(status, claim, roles, settings, people, rates, sheets, store, log,
76:                                m -> move[0] = m);
77:                        Rollup before = rollups.snapshot(sheet);
78:                        StatusChange[] change = new StatusChange[1];
79:                        new ApplyStatus().apply(status, move[0], claim, store, people, rates, settings, sheets, periods,
80:                                voidReasons, c -> change[0] = c);
81:                        new SaveClaim().save(status, claim, store, log);
82:                        new AuditClaimStatus().audit(status, move[0], claim, change[0], before, people, audit, rollups,
83:                                watches);
84:                        return true;
85:                    } catch (InvalidSheetException e) {
86:                        tx.setRollbackOnly();
87:                        return false;
88:                    }
89:                }));
90:            } finally {
91:                if (done) {
92:                    audit.release();
93:                } else {
94:                    audit.discard();
95:                }
96:            }
97:            if (done) {
98:                voided++;
99:            } else {
100:                refused++;
101:            }
102:        }
103:        result.set(new BulkVoidResult(voided, refused));
104:    }
