23:/** Takes a statement of the person on the sheet's today: their due-total (the sum of the figures of
24: *  their claims that count; n/a when their grade in force today has no rate today and no counting claim
25: *  keeps a fixed figure or a figure at another grade, the one in force on its date), binding each counting claim to its due as shown now, late charge and floor included (a claim already bound
26: *  keeps the due it was bound to) and unbinding the rest. A settled claim keeps its fixed figure. The due-total is
27: *  at most the sheet's cap.
28: *  <p>
29: *  Taken as of a date (on or before the sheet's today), everything is as it stood at the end of that date
30: *  (see {@link net.officefloor.hq.app.history.History}): their claims that counted then are bound to their
31: *  figures then, and the date stands in for the sheet's today in every figure (grade and rate in force, floor,
32: *  late charges, holds, retirement, cap); every other claim of theirs is unbound. The statement is dated that
33: *  date. Refused when the date is after the sheet's today, or the person was not on the sheet then. */
34:public class TakeStatement {
35:    public void take(@Val StatementRequest request, @Val Person person, ClaimStore claims, RateStore rates,
36:            SheetStore sheets, SettingStore settings, PersonStore people, StatementStore statements,
37:            Out<Statement> statementOut) throws InvalidSheetException {
38:        String sheetId = person.getSheetId();
39:        LocalDate today = sheets.today(sheetId);
40:        LocalDate asOf = request.asOfDate();
41:        if (asOf != null && asOf.isAfter(today)) {
42:            throw new InvalidSheetException("The statement date is after the sheet's today");
43:        }
44:        // Locked, so a status change or another statement made at once waits for this one.
45:        List<Claim> bound = claims.listForUpdate(sheetId, person.getId());
46:        // What the figures follow: the store as it is now, or as it stood at the end of the date.
47:        LocalDate on = today;
48:        Person then = person;
49:        List<Claim> all;
50:        Map<Long, Claim> was = new HashMap<>();
51:        if (asOf == null) {
52:            all = claims.list(sheetId);
53:            bound.forEach(claim -> was.put(claim.getId(), claim));
54:        } else {
55:            on = asOf;
56:            then = people.findAsOf(sheetId, person.getId(), asOf);
57:            if (then == null) {
58:                throw new InvalidSheetException("The person was not on the sheet on " + asOf);
59:            }
60:            rates = rates.asOf(asOf);
61:            settings = settings.asOf(asOf);
62:            all = claims.listAsOf(sheetId, asOf);
63:            all.stream().filter(claim -> claim.getPersonId() == person.getId()).forEach(claim -> was.put(claim.getId(), claim));
64:        }
65:        LocalDate policy = settings.policyDate(sheetId);
66:        Rounding rounding = new Rounding(policy != null ? policy : on, settings.roundings(sheetId), all);
67:        Person whose = then;
68:        Lateness lateness = new Lateness(settings.latePcts(sheetId), settings.floors(sheetId), on, rounding,
69:                Lateness.graced(settings.graces(sheetId), id -> id == whose.getId() ? whose : null));
70:        BigDecimal total = BigDecimal.ZERO.setScale(2);
71:        boolean fixed = false;
72:        int counted = 0;
73:        for (Claim live : bound) {
74:            // The claim as it stood then (itself when taken now); null when it was not theirs then.
75:            Claim claim = was.get(live.getId());
76:            // An OPEN (or PENDING) claim of a retired person counts in no live total unless a statement bound
77:            // it, so a statement neither counts nor binds it; one it bound before stays counted. A deferred
78:            // claim counts in no total until the sheet's today reaches its date: a statement leaves it unbound.
79:            boolean counts = claim != null && RollupService.counts(claim, then, on);
80:            BigDecimal figure = null;
81:            boolean na = false;
82:            if (counts) {
83:                figure = ClaimFigure.of(claim, rates.forClaim(claim).find(sheetId, then.gradeOn(claim.getDate()), claim.getDate()), rounding);
84:                counted++;
85:                if (figure != null) {
86:                    // Bound as shown: its charge and floor stop following the sheet's today.
87:                    figure = lateness.dueOf(claim, figure);
88:                    total = total.add(figure);
89:                }
90:                // A figure at a grade other than the one in force today, or at a rate that ended before
91:                // today, does not hang on today's grade's rate.
92:                fixed |= claim.getSettledDue() != null || (claim.isBound() && claim.getStatedDue() != null)
93:                        || (figure != null && (!then.gradeOn(claim.getDate()).equals(then.gradeOn(on))
94:                                || rates.forClaim(claim).endsBefore(sheetId, then.gradeOn(claim.getDate()), claim.getDate(), on)));
95:                // A claim whose rate ended before its date is bound to n/a, so a later rate leaves it so.
96:                na = figure == null && (claim.isBound()
97:                        || (claim.getSettledDue() == null && rates.forClaim(claim).ended(sheetId, then.gradeOn(claim.getDate()), claim.getDate())));
98:            }
99:            live.setStated(counts);
100:            live.setStatedDue(figure);
101:            live.setStatedNa(na);
102:            claims.bind(live);
103:        }
104:        boolean na = rates.find(sheetId, then.gradeOn(on), on) == null && !fixed;
105:        Statement statement = new Statement(person.getId(), on,
106:                na ? null : SettingStore.capped(total, settings.cap(sheetId)), counted);
107:        statements.add(sheetId, statement, request.user());
108:        statementOut.set(statement);
109:    }
