25:/**
26: * Checks every pasted line with exactly the claim form's rules before anything is stored: the name
27: * (or an alias) must be on the sheet (ignoring case and the spaces around it), the amount a number with up to two
28: * decimals (a negative one names no claim it corrects, so is refused), the date (blank for the
29: * entry date while it is set, else the sheet's today) due by (with the terms it would get) a date in no closed period and not after the person is retired from. The note is the rest
30: * of the line, commas and all, less a closing " #<reference>", which is the claim's external reference: one
31: * already on the sheet or given by an earlier line, compared without regard to case, is refused. Blank lines are skipped; a paste with no line is refused.
32: * A line naming a person, date and note that match one of their claims as they stood before the paste (void and deleted
33: * ones aside) updates the newest such DRAFT instead of adding a claim; one whose matches include no DRAFT is refused.
34: */
35:public class ValidatePaste {
36:    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteRequest request,
37:            SettingStore settings, PersonStore people, PeriodStore periods, ClaimStore claims, Out<PasteInput> pasted, RoleStore roles, HolidayStore holidays) throws InvalidSheetException {
38:        roles.refuseChange(sheetId.trim(), request == null ? null : request.user());
39:        String sheet = sheetId.trim();
40:        String text = request == null || request.text() == null ? "" : request.text();
41:        List<PastedClaim> pastedClaims = new ArrayList<>();
42:        String[] lines = text.split("\\r?\\n");
43:        Set<String> refs = new HashSet<>();
44:        // The claims as they stood before the paste, newest first: what a line may match.
45:        List<Claim> before = claims.list(sheet);
46:        for (int i = 0; i < lines.length; i++) {
47:            String line = lines[i];
48:            if (line.trim().isEmpty()) {
49:                continue;
50:            }
51:            String[] fields = line.split(",", 4);
52:            if (fields.length < 2) {
53:                throw new InvalidSheetException("Line " + (i + 1) + " must be name,amount,date,note");
54:            }
55:            try {
56:                Person person = people.findByName(sheet, fields[0]);
57:                if (person == null) {
58:                    throw new InvalidSheetException("No such person: " + fields[0].trim());
59:                }
60:                String note = fields.length > 3 ? fields[3].trim() : "";
61:                String ref = "";
62:                int hash = note.lastIndexOf(" #");
63:                if (hash >= 0 && !note.substring(hash + 2).trim().isEmpty()) {
64:                    ref = note.substring(hash + 2).trim();
65:                    note = note.substring(0, hash);
66:                }
67:                ClaimInput claim = ClaimAdding.check(sheet, person, new ClaimRequest(fields[1],
68:                        fields.length > 2 ? fields[2] : "", note, request.user(), "", ref),
69:                        settings, periods, claims, holidays);
70:                if (claim.ref() != null && !refs.add(claim.ref().toLowerCase(Locale.ROOT))) {
71:                    throw new InvalidSheetException("The reference " + claim.ref() + " is given twice");
72:                }
73:                pastedClaims.add(new PastedClaim(person, claim, matchedDraft(before, person, claim)));
74:            } catch (InvalidSheetException e) {
75:                throw new InvalidSheetException("Line " + (i + 1) + ": " + e.getMessage());
76:            }
77:        }
78:        if (pastedClaims.isEmpty()) {
79:            throw new InvalidSheetException("Paste at least one line of name,amount,date,note");
80:        }
81:        pasted.set(new PasteInput(pastedClaims));
82:    }
84:    /** The newest DRAFT of the person's claims (void and deleted ones aside) with the line's date and
85:     *  note, null when none has them; refused when some have them but none is a DRAFT. */
86:    private static Long matchedDraft(List<Claim> before, Person person, ClaimInput line) throws InvalidSheetException {
87:        boolean matched = false;
88:        for (Claim c : before) {
89:            if (c.getPersonId() != person.getId() || c.getStatus() == ClaimStatus.VOID
90:                    || c.getStatus() == ClaimStatus.DELETED || !line.date().equals(c.getDate())
91:                    || !noteOf(line.note()).equals(noteOf(c.getNote()))) {
92:                continue;
93:            }
94:            if (c.getStatus() == ClaimStatus.DRAFT) {
95:                return c.getId();
96:            }
97:            matched = true;
98:        }
99:        if (matched) {
100:            throw new InvalidSheetException("It matches a claim of " + person.getName() + " that is no longer a DRAFT");
101:        }
102:        return null;
103:    }
105:    private static String noteOf(String note) {
106:        return note == null ? "" : note.trim();
107:    }
108:}
