27:/** Takes each pasted line in order: adds its claim as the claim form would (a DRAFT recorded as
28: *  CLAIM_ADDED), or edits the DRAFT it matched to its amount (CLAIM_EDITED when that changes), then
29: *  opens it by the user exactly as the open button would. All or nothing: the first refusal rolls every
30: *  line back, drops their audit records and refuses the paste. */
31:public class SavePasted {
32:    public void save(@Val PasteInput pasted, ClaimStore store, SettingStore settings, ClaimLogStore log,
33:            PeriodStore periods, RollupService rollups, Audit audit, HolidayStore holidays, PersonStore people,
34:            SheetStore sheets, RoleStore roles, RateStore rates, WatchStore watches, VoidReasonStore voidReasons,
35:            ClaimLineStore lines, PlatformTransactionManager transactions, Out<PasteResult> result)
36:            throws InvalidSheetException {
37:        TransactionTemplate nested = new TransactionTemplate(transactions);
38:        nested.setPropagationBehavior(TransactionDefinition.PROPAGATION_NESTED);
39:        InvalidSheetException[] refused = new InvalidSheetException[1];
40:        audit.hold();
41:        boolean done = false;
42:        try {
43:            done = Boolean.TRUE.equals(nested.execute(tx -> {
44:                int line = 0;
45:                for (PastedClaim p : pasted.claims()) {
46:                    line++;
47:                    try {
48:                        Claim claim;
49:                        if (p.draftId() == null) {
50:                            claim = ClaimAdding.add(p.claim(), p.person(), store, settings, log, periods, rollups,
51:                                    audit, holidays);
52:                        } else {
53:                            claim = store.find(p.person().getSheetId(), p.draftId());
54:                            if (claim == null) {
55:                                throw new InvalidSheetException("The claim it matched is no longer on the sheet");
56:                            }
57:                            ClaimOpening.editAmount(claim, p.claim(), store, lines, people, rollups, audit);
58:                        }
59:                        ClaimOpening.open(claim, p.claim().user(), store, people, periods, settings, sheets, roles,
60:                                rates, log, rollups, audit, watches, voidReasons);
61:                    } catch (InvalidSheetException e) {
62:                        refused[0] = new InvalidSheetException("Line " + line + ": " + e.getMessage());
63:                        tx.setRollbackOnly();
64:                        return false;
65:                    }
66:                }
67:                return true;
68:            }));
69:        } finally {
70:            if (done) {
71:                audit.release();
72:            } else {
73:                audit.discard();
74:            }
75:        }
76:        if (!done) {
77:            throw refused[0] != null ? refused[0] : new InvalidSheetException("The paste was refused");
78:        }
79:        result.set(new PasteResult(pasted.claims().size()));
80:    }
81:}
