24:/**
25: * For every plan on the sheet in the order they were added, adds a DRAFT claim of the plan's amount, dated that
26: * day with an empty note, for every plan date (the start, then every N days, or a monthly plan's day in each month) up to its end and the sheet's today
27: * that it has made none for yet, as the claim form would (recorded as CLAIM_ADDED). A date the claim form refuses
28: * is skipped, and tried again on the next generate. A viewer makes none: the answer is 0, storing and recording nothing.
29: */
30:public class GeneratePlanClaims {
31:    public void generate(@PathVariable("sheetId") String sheetId, @Val PlanGenerateRequest request, PlanStore plans,
32:            PersonStore people, SheetStore sheets, ClaimStore claims, SettingStore settings, ClaimLogStore log,
33:            PeriodStore periods, RollupService rollups, Audit audit, HolidayStore holidays, RoleStore roles,
34:            Out<PlanGenerateResult> result) {
35:        String sheet = sheetId.trim();
36:        LocalDate today = sheets.today(sheet);
37:        int made = 0;
38:        if (roles.find(sheet, request.user()) == Role.VIEWER) {
39:            result.set(new PlanGenerateResult(made));
40:            return;
41:        }
42:        for (Plan plan : plans.list(sheet)) {
43:            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
44:            for (LocalDate d : plan.dates(last)) {
45:                if (plans.made(plan.id(), d)) {
46:                    continue;
47:                }
48:                Person person = people.find(sheet, plan.personId());
49:                if (person == null) {
50:                    break;
51:                }
52:                ClaimInput input;
53:                try {
54:                    input = ClaimAdding.check(sheet, person, new ClaimRequest(plan.amount().toPlainString(),
55:                            d.toString(), "", request.user(), "", ""), settings, periods, claims, holidays);
56:                } catch (InvalidSheetException e) {
57:                    continue;
58:                }
59:                ClaimAdding.add(input, person, claims, settings, log, periods, rollups, audit, holidays);
60:                plans.markMade(plan.id(), d);
61:                made++;
62:            }
63:        }
64:        result.set(new PlanGenerateResult(made));
65:    }
66:}
