9:/** A person's plan: a DRAFT claim of the amount on every plan date up to the end; {@code generated} how many
10: *  claims it has made so far. The plan dates are the start then every {@code every} days, or, for a monthly plan
11: *  ({@code day} set, {@code every} null), {@link #dates(LocalDate)}. */
12:public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every,
13:        Integer day, LocalDate end, int generated) {
15:    /** The plan dates up to and including {@code last}, in order. A monthly plan's are its day in every month
16:     *  from the start's month, a day beyond the month's length falling on its last day, those before the start
17:     *  left out. */
18:    public List<LocalDate> dates(LocalDate last) {
19:        List<LocalDate> dates = new ArrayList<>();
20:        if (day == null) {
21:            for (LocalDate d = start; !d.isAfter(last); d = d.plusDays(every)) {
22:                dates.add(d);
23:            }
24:            return dates;
25:        }
26:        for (YearMonth m = YearMonth.from(start); !m.atDay(1).isAfter(last); m = m.plusMonths(1)) {
27:            LocalDate d = m.atDay(Math.min(day, m.lengthOfMonth()));
28:            if (!d.isBefore(start) && !d.isAfter(last)) {
29:                dates.add(d);
30:            }
31:        }
32:        return dates;
33:    }
35:    /** The first {@code count} plan dates after {@code today} and on or before the end, in order. */
36:    public List<LocalDate> nextDates(LocalDate today, int count) {
37:        return dates(end).stream().filter(d -> d.isAfter(today)).limit(count).toList();
38:    }
39:}

